jektvorlagen</h3><?php foreach($templates as $t):?><article><div><strong><?=pmh($t['name'])?></strong><p><?=pmh($t['description'])?></p></div><span class="pm-status"><?=$t['project_type']==='event'?'Veranstaltung':'Projekt'?></span><a class="pm-button small secondary" href="projects.php?view=edit_template&id=<?=$t['id']?>">Vorlage bearbeiten</a></article><?php endforeach;if(!$templates):?><p class="pm-muted">Noch keine Projektvorlagen vorhanden.</p><?php endif;?></div><div class="pm-template-list"><h3>Allgemeine Aufgabenvorlagen</h3><?php foreach($taskTemplates as $t):?><article><div><strong><?=pmh($t['title'])?></strong><p><?=pmh($t['description'])?></p></div><span class="pm-offset">Beginn <?= $t['start_offset_days']===null?'—':(int)$t['start_offset_days'].' T.' ?> · Fällig <?= $t['due_offset_days']===null?'—':(int)$t['due_offset_days'].' T.' ?></span></article><?php endforeach;if(!$taskTemplates):?><p class="pm-muted">Noch keine allgemeinen Aufgabenvorlagen vorhanden.</p><?php endif;?></div></section>
